window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f11b3ef251055cc9"]={"versions": [{"id": "FIG-f11b3ef251055cc9", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Prozessdiagramm (Software &amp; Systems Process Engineering Metamodel) im Kontext der AUTOSAR-Timing-Analyse (<code>AUTOSAR_TR_TimingAnalysis</code>). Dargestellt ist der ECU-spezifische Use Case „Collect Timing Information of a SW-C“, aufgeteilt in Aktivitäten zur Erfassung von Timing-Anforderungen sowie zur Generierung von Timing-Modellen für Software-Komponenten mittels modell- und implementationsbasierter Analyse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert SPEM-Aktivitäten (Task Definitions bzw. Activities, gelbe Pfeilblöcke) und Arbeitsergebnisse (Work Products, Dokumentensymbole) mit gerichteten Stereotyp-Beziehungen (<code>«input»</code> und <code>«output»</code>):</p>\n<ul class=\"fig-list\"><li><strong>Aktivitäten</strong>:\n<ul class=\"fig-list\"><li><code>Collect Timing Requirements</code>: Erfasst Timing-Vorgaben.\n</li><li><code>Perform Implementation-Based Timing Analysis</code>: Führt code- bzw. implementationsbasierte Timing-Analysen durch.\n</li><li><code>Perform Model-Based Timing Analysis</code>: Führt modellbasierte Timing-Analysen durch.\n</li><li><code>Create Timing Model (SWC)</code>: Erstellt das Timing-Modell der SW-C aus den Analyseergebnissen.\n</li></ul>\n</li><li><strong>Arbeitsergebnisse / Artefakte</strong>:\n<ul class=\"fig-list\"><li><code>Functional Requirements</code>: Funktionale Anforderungen (Input für <code>Collect Timing Requirements</code>).\n</li><li><code>Timing Requirements</code>: Spezifizierte Timing-Anforderungen (Output von <code>Collect Timing Requirements</code>).\n</li><li><code>Implementation</code>: Software-Code/Implementierung (Input für <code>Perform Implementation-Based Timing Analysis</code>).\n</li><li><code>Timing Model</code>: Vorhandenes Timing-Modell (Input für <code>Perform Model-Based Timing Analysis</code>).\n</li><li><code>Timing Analysis Report</code>: Analysebericht (Output beider Analyseaktivitäten, Input für <code>Create Timing Model (SWC)</code>).\n</li><li><code>Timing Model SWC</code>: Fertiges SW-C-Timing-Modell (Output von <code>Create Timing Model (SWC)</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei parallele bzw. komplementäre Pfade:</p>\n<ol class=\"fig-list\"><li><strong>Anforderungspfad</strong>: <code>Functional Requirements</code> dienen als <code>«input»</code> für <code>Collect Timing Requirements</code>, woraus als <code>«output»</code> die <code>Timing Requirements</code> hervorgehen.\n</li><li><strong>Timing-Modellierungspfad</strong>:\n<ul class=\"fig-list\"><li>Die Aktivität <code>Perform Implementation-Based Timing Analysis</code> nimmt <code>Implementation</code> als <code>«input»</code>.\n</li><li>Die Aktivität <code>Perform Model-Based Timing Analysis</code> nimmt <code>Timing Model</code> als <code>«input»</code>.\n</li><li>Beide Analyseaktivitäten liefern als <code>«output»</code> den <code>Timing Analysis Report</code>.\n</li><li>Der <code>Timing Analysis Report</code> fungiert als <code>«input»</code> für die nachgelagerte Aktivität <code>Create Timing Model (SWC)</code>, welche als finalen <code>«output»</code> das Artefakt <code>Timing Model SWC</code> erzeugt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als methodischer Leitfaden für den AUTOSAR-Entwicklungsprozess zur Erstellung von Timing-Beschreibungen (AUTOSAR Timing Extensions) auf Software-Komponenten-Ebene. Entwickler und Tool-Hersteller müssen sicherstellen, dass Timing-Analysen entweder aus der Code-Implementierung (z. B. statische WCET-Analyse, Messungen) oder aus bestehenden Timing-Modellen konsolidierte Reports erzeugen, welche die standardkonforme Parametrierung des <code>Timing Model SWC</code> ermöglichen.</p>"}, {"id": "FIG-29cedc0936538a44", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Prozessdiagramm (Software &amp; Systems Process Engineering Metamodel) im Kontext der AUTOSAR-Timing-Analyse (<code>AUTOSAR_TR_TimingAnalysis</code>). Dargestellt ist der ECU-spezifische Use Case „Collect Timing Information of a SW-C“, aufgeteilt in Aktivitäten zur Erfassung von Timing-Anforderungen sowie zur Generierung von Timing-Modellen für Software-Komponenten mittels modell- und implementationsbasierter Analyse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert SPEM-Aktivitäten (Task Definitions bzw. Activities, gelbe Pfeilblöcke) und Arbeitsergebnisse (Work Products, Dokumentensymbole) mit gerichteten Stereotyp-Beziehungen (<code>«input»</code> und <code>«output»</code>):</p>\n<ul class=\"fig-list\"><li><strong>Aktivitäten</strong>:\n<ul class=\"fig-list\"><li><code>Collect Timing Requirements</code>: Erfasst Timing-Vorgaben.\n</li><li><code>Perform Implementation-Based Timing Analysis</code>: Führt code- bzw. implementationsbasierte Timing-Analysen durch.\n</li><li><code>Perform Model-Based Timing Analysis</code>: Führt modellbasierte Timing-Analysen durch.\n</li><li><code>Create Timing Model (SWC)</code>: Erstellt das Timing-Modell der SW-C aus den Analyseergebnissen.\n</li></ul>\n</li><li><strong>Arbeitsergebnisse / Artefakte</strong>:\n<ul class=\"fig-list\"><li><code>Functional Requirements</code>: Funktionale Anforderungen (Input für <code>Collect Timing Requirements</code>).\n</li><li><code>Timing Requirements</code>: Spezifizierte Timing-Anforderungen (Output von <code>Collect Timing Requirements</code>).\n</li><li><code>Implementation</code>: Software-Code/Implementierung (Input für <code>Perform Implementation-Based Timing Analysis</code>).\n</li><li><code>Timing Model</code>: Vorhandenes Timing-Modell (Input für <code>Perform Model-Based Timing Analysis</code>).\n</li><li><code>Timing Analysis Report</code>: Analysebericht (Output beider Analyseaktivitäten, Input für <code>Create Timing Model (SWC)</code>).\n</li><li><code>Timing Model SWC</code>: Fertiges SW-C-Timing-Modell (Output von <code>Create Timing Model (SWC)</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei parallele bzw. komplementäre Pfade:</p>\n<ol class=\"fig-list\"><li><strong>Anforderungspfad</strong>: <code>Functional Requirements</code> dienen als <code>«input»</code> für <code>Collect Timing Requirements</code>, woraus als <code>«output»</code> die <code>Timing Requirements</code> hervorgehen.\n</li><li><strong>Timing-Modellierungspfad</strong>:\n<ul class=\"fig-list\"><li>Die Aktivität <code>Perform Implementation-Based Timing Analysis</code> nimmt <code>Implementation</code> als <code>«input»</code>.\n</li><li>Die Aktivität <code>Perform Model-Based Timing Analysis</code> nimmt <code>Timing Model</code> als <code>«input»</code>.\n</li><li>Beide Analyseaktivitäten liefern als <code>«output»</code> den <code>Timing Analysis Report</code>.\n</li><li>Der <code>Timing Analysis Report</code> fungiert als <code>«input»</code> für die nachgelagerte Aktivität <code>Create Timing Model (SWC)</code>, welche als finalen <code>«output»</code> das Artefakt <code>Timing Model SWC</code> erzeugt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als methodischer Leitfaden für den AUTOSAR-Entwicklungsprozess zur Erstellung von Timing-Beschreibungen (AUTOSAR Timing Extensions) auf Software-Komponenten-Ebene. Entwickler und Tool-Hersteller müssen sicherstellen, dass Timing-Analysen entweder aus der Code-Implementierung (z. B. statische WCET-Analyse, Messungen) oder aus bestehenden Timing-Modellen konsolidierte Reports erzeugen, welche die standardkonforme Parametrierung des <code>Timing Model SWC</code> ermöglichen.</p>"}], "trans": [{"from": "FIG-f11b3ef251055cc9", "to": "FIG-29cedc0936538a44", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
